INSERT INTO world.creature_text (CreatureID, GroupID, ID, Text, Type, Language, Probability, Emote, Duration, Sound, BroadcastTextId, TextRange, comment) VALUES
(11799, 0, 0, 'Good work, $n!  Complete your trial by speaking with me.  Time continues to slip away until you do so!', 12, 0, 100, 0, 0, 0, 7611, 0, 'VMaNGOS dbscript'),
(10340, 0, 0, 'You have come too far to fail. Stand back, mortals.', 14, 0, 100, 5, 0, 0, 5760, 0, 'VMaNGOS dbscript'),
(10340, 1, 0, 'You will suffer in this defeat, Nefarian!', 14, 0, 100, 0, 0, 0, 5761, 0, 'VMaNGOS dbscript'),
(10162, 16, 0, 'Enough! Playtime is over!', 14, 0, 100, 0, 0, 0, 5596, 0, 'VMaNGOS dbscript'),
(10162, 17, 0, 'Vaelastrasz, when this world belongs to the black flight, your flight shall know its end.', 14, 0, 100, 0, 0, 0, 5776, 0, 'VMaNGOS dbscript'),
(10162, 18, 0, 'But for now, your death will have to suffice...', 14, 0, 100, 0, 0, 0, 5777, 0, 'VMaNGOS dbscript'),
(10340, 2, 0, 'All is not lost! Battle these beasts without fear. Your wounds I shall heal, bones I shall mend. Be renewed, heroes!', 14, 0, 100, 1, 0, 0, 5748, 0, 'VMaNGOS dbscript');
